class Solution {
public:
    vector<int> numIslands2(int m, int n, vector<vector<int>>& positions) {
        vector<int> parent(m * n, -1);
        function<int(int)> find = [&](int x) {
            return parent[x] == x ? x : (parent[x] = find(parent[x]));
        };
        vector<int> res;
        int count = 0;
        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (const auto& pos : positions) {
            int r = pos[0], c = pos[1];
            int key = r * n + c;
            if (parent[key] != -1) {
                res.push_back(count);
                continue;
            }
            parent[key] = key;
            count++;
            for (auto& d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                int nkey = nr * n + nc;
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && parent[nkey] != -1) {
                    int root1 = find(key), root2 = find(nkey);
                    if (root1 != root2) {
                        parent[root1] = root2;
                        count--;
                    }
                }
            }
            res.push_back(count);
        }
        return res;
    }
};

class Solution {
    public List<Integer> numIslands2(int m, int n, int[][] positions) {
        int[] parent = new int[m * n];
        java.util.Arrays.fill(parent, -1);
        List<Integer> res = new ArrayList<>();
        int count = 0;
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] pos : positions) {
            int r = pos[0], c = pos[1];
            int key = r * n + c;
            if (parent[key] != -1) {
                res.add(count);
                continue;
            }
            parent[key] = key;
            count++;
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                int nkey = nr * n + nc;
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && parent[nkey] != -1) {
                    int root1 = find(parent, key), root2 = find(parent, nkey);
                    if (root1 != root2) {
                        parent[root1] = root2;
                        count--;
                    }
                }
            }
            res.add(count);
        }
        return res;
    }
    private int find(int[] parent, int x) {
        return parent[x] == x ? x : (parent[x] = find(parent, parent[x]));
    }
}

/**
 * @param {number} m
 * @param {number} n
 * @param {number[][]} positions
 * @return {number[]}
