var numIslands2 = function(m, n, positions) {
    const parent = new Array(m * n).fill(-1);
    const find = (x) => parent[x] === x ? x : (parent[x] = find(parent[x]));
    const res = [];
    let count = 0;
    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    for (const [r, c] of positions) {
        const key = r * n + c;
        if (parent[key] !== -1) {
            res.push(count);
            continue;
        }
        parent[key] = key;
        count++;
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            const nkey = nr * n + nc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && parent[nkey] !== -1) {
                const r1 = find(key), r2 = find(nkey);
                if (r1 !== r2) {
                    parent[r1] = r2;
                    count--;
                }
            }
        }
        res.push(count);
    }
    return res;
};
